package com.knightfinder;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import javax.inject.Inject;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

class KnightFinderClient
{
	private static final HttpUrl KNIGHTS_URL = HttpUrl.get("https://knights.shep.rip/api/v1/knights");
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final Type SPLIT_LIST = new TypeToken<List<KnightSplit>>() { }.getType();
	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	KnightFinderClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/**
	 * @param fresh asks any cache between here and the server for a new copy, for the moment right
	 *              after this client changed something.
	 */
	void list(boolean fresh, Consumer<List<KnightSplit>> success, Consumer<String> failure)
	{
		Request.Builder builder = new Request.Builder().url(KNIGHTS_URL).get();
		if (fresh) builder.header("Cache-Control", "no-cache");
		httpClient.newCall(builder.build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException exception)
			{
				failure.accept("Knight server unavailable");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					if (!response.isSuccessful() || response.body() == null)
					{
						failure.accept("Knight server returned " + response.code());
						return;
					}
					List<KnightSplit> splits = gson.fromJson(response.body().charStream(), SPLIT_LIST);
					success.accept(splits == null ? Collections.emptyList() : splits);
				}
				catch (RuntimeException exception)
				{
					failure.accept("Invalid knight response");
				}
			}
		});
	}

	void report(KnightSplit split, Runnable success, Consumer<String> failure)
	{
		Request request = new Request.Builder().url(KNIGHTS_URL)
			.post(RequestBody.create(JSON, gson.toJson(split))).build();
		execute(request, success, failure);
	}

	void delete(int world, Runnable success, Consumer<String> failure)
	{
		HttpUrl url = KNIGHTS_URL.newBuilder().addPathSegment(Integer.toString(world)).build();
		execute(new Request.Builder().url(url).delete().build(), success, failure);
	}

	private void execute(Request request, Runnable success, Consumer<String> failure)
	{
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException exception)
			{
				failure.accept("Knight server unavailable");
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response closeable = response)
				{
					if (response.isSuccessful()) success.run();
					else failure.accept("Knight server returned " + response.code());
				}
			}
		});
	}
}

package com.knightfinder;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(KnightFinderConfig.GROUP)
public interface KnightFinderConfig extends Config
{
	String GROUP = "knight-finder";

	@ConfigItem(
		keyName = "sharingEnabled",
		name = "Enable shared knights",
		description = "Shares knights pinned on your world and lists the ones other plugin users have found",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 0
	)
	default boolean sharingEnabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Highlight pinned knight",
		description = "Outlines a knight on your world once it counts as pinned, with how many people are on it",
		position = 1
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyNewSplit",
		name = "Notify on new knight",
		description = "Sends a notification when a pinned knight appears on a world you are not on",
		position = 2
	)
	default boolean notifyNewSplit()
	{
		return false;
	}
}

package com.knightfinder;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Insets;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

class KnightFinderPanel extends PluginPanel
{
	private static final int REFRESH_THROTTLE_MS = 5000;
	private static final int BODY_WRAP_WIDTH = 160;
	/** A knight not heard from for this long is probably gone; the server drops it soon after. */
	private static final long STALE_MILLIS = 45_000L;
	private static final String DISABLED = "Shared knights are disabled";
	private static final Color GREEN = new Color(90, 200, 120);
	private static final Color BLUE = new Color(80, 155, 255);

	private final JPanel list = new JPanel();
	private final JLabel status = new JLabel(DISABLED, SwingConstants.CENTER);
	private final JButton refresh = new JButton("Refresh");
	private final Runnable refreshHandler;
	private final Consumer<Boolean> activeHandler;
	private boolean showingSplits;

	KnightFinderPanel(Runnable refreshHandler, Consumer<Boolean> activeHandler)
	{
		this.refreshHandler = refreshHandler;
		this.activeHandler = activeHandler;
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("Knight Finder");
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.PLAIN, 18f));
		title.setForeground(Color.WHITE);
		refresh.setFont(FontManager.getRunescapeSmallFont());
		refresh.setToolTipText("Refresh now");
		refresh.setFocusable(false);
		refresh.setMargin(new Insets(0, 0, 0, 0));
		refresh.setPreferredSize(new Dimension(56, 20));
		refresh.addActionListener(event -> requestRefresh());

		JPanel titleRow = new JPanel(new BorderLayout(6, 0));
		titleRow.setOpaque(false);
		titleRow.add(title, BorderLayout.CENTER);
		titleRow.add(refresh, BorderLayout.EAST);
		add(titleRow, BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setOpaque(false);
		// Anchoring the list to the top stops BoxLayout from centring the cards in the panel.
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setOpaque(false);
		wrapper.add(list, BorderLayout.NORTH);
		add(wrapper, BorderLayout.CENTER);

		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(Color.LIGHT_GRAY);
		status.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
		add(status, BorderLayout.SOUTH);
	}

	@Override
	public void onActivate()
	{
		activeHandler.accept(true);
	}

	@Override
	public void onDeactivate()
	{
		activeHandler.accept(false);
	}

	void setDisabled()
	{
		list.removeAll();
		showingSplits = false;
		status.setText(DISABLED);
		revalidate();
		repaint();
	}

	void setLoading()
	{
		// Only announce a refresh when there is nothing on screen, otherwise the status flickers every cycle.
		if (!showingSplits) status.setText("Looking for knights...");
	}

	void setError(String message)
	{
		status.setText(message);
	}

	void setSplits(List<KnightSplit> incoming, int currentWorld)
	{
		long now = Instant.now().toEpochMilli();
		List<KnightSplit> sorted = incoming == null ? new ArrayList<>() : new ArrayList<>(incoming);
		// Fresh reports first, and among those the busiest knight, which is the one most surely still there.
		sorted.sort(Comparator.comparing((KnightSplit split) -> now - split.getUpdatedAt() >= STALE_MILLIS)
			.thenComparing(Comparator.comparingInt(KnightSplit::getPickpockets).reversed())
			.thenComparingInt(KnightSplit::getWorld));
		list.removeAll();
		if (sorted.isEmpty())
		{
			list.add(Box.createVerticalStrut(12));
			list.add(placeholder("No pinned knights right now"));
		}
		else
		{
			for (int i = 0; i < sorted.size(); i++)
			{
				if (i > 0) list.add(Box.createVerticalStrut(6));
				list.add(card(sorted.get(i), currentWorld, now));
			}
		}
		showingSplits = !sorted.isEmpty();
		status.setText(sorted.size() + (sorted.size() == 1 ? " pinned knight" : " pinned knights"));
		revalidate();
		repaint();
	}

	private JLabel placeholder(String text)
	{
		JLabel label = new JLabel(text, SwingConstants.CENTER);
		label.setForeground(Color.LIGHT_GRAY);
		label.setAlignmentX(CENTER_ALIGNMENT);
		return label;
	}

	private void requestRefresh()
	{
		// Throttle manual refreshes so the button cannot be used to hammer the server.
		refresh.setEnabled(false);
		Timer unlock = new Timer(REFRESH_THROTTLE_MS, event -> refresh.setEnabled(true));
		unlock.setRepeats(false);
		unlock.start();
		refreshHandler.run();
	}

	private JPanel card(KnightSplit split, int currentWorld, long now)
	{
		boolean stale = now - split.getUpdatedAt() >= STALE_MILLIS;
		boolean here = currentWorld > 0 && currentWorld == split.getWorld();
		Color accent = split.isHeld() ? GREEN : BLUE;
		if (stale) accent = accent.darker().darker();

		JPanel card = new JPanel(new BorderLayout(0, 3));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(6, 7, 6, 7)));
		card.setAlignmentX(LEFT_ALIGNMENT);

		JLabel world = new JLabel("World " + split.getWorld());
		world.setFont(FontManager.getRunescapeBoldFont());
		world.setForeground(stale ? ColorScheme.LIGHT_GRAY_COLOR : Color.WHITE);

		JLabel method = new JLabel(split.isHeld() ? "Held by splasher" : "Trapped");
		method.setFont(FontManager.getRunescapeSmallFont());
		method.setForeground(accent);
		method.setToolTipText(split.isHeld()
			? "A player is keeping the knight in combat - it stays as long as they do"
			: "The knight is boxed in by walls - it stays until someone lets it out");

		JPanel header = new JPanel(new BorderLayout(6, 0));
		header.setOpaque(false);
		header.add(world, BorderLayout.WEST);
		header.add(method, BorderLayout.CENTER);
		if (here) header.add(hereLabel(), BorderLayout.EAST);

		// Wrapped, so a long spot name and the count fit the sidebar instead of being clipped.
		JLabel body = new JLabel("<html><div width=" + BODY_WRAP_WIDTH + ">"
			+ escape(split.getSpot() == null ? "Unknown spot" : split.getSpot())
			+ " · " + KnightOverlay.people(split.getPickpockets()) + "</div></html>");
		body.setForeground(stale ? Color.GRAY : ColorScheme.LIGHT_GRAY_COLOR);

		JLabel pinned = new JLabel("pinned " + minutes(now - split.getStartedAt()));
		pinned.setFont(FontManager.getRunescapeSmallFont());
		pinned.setForeground(Color.GRAY);
		pinned.setToolTipText("How long this knight has been reported pinned");

		JLabel age = new JLabel(age(now - split.getUpdatedAt()));
		age.setFont(FontManager.getRunescapeSmallFont());
		age.setForeground(Color.GRAY);
		if (stale) age.setToolTipText("Nobody has seen this knight for a while - it may have got away");

		JPanel footer = new JPanel(new BorderLayout(6, 0));
		footer.setOpaque(false);
		footer.add(pinned, BorderLayout.WEST);
		footer.add(age, BorderLayout.EAST);

		card.add(header, BorderLayout.NORTH);
		card.add(body, BorderLayout.CENTER);
		card.add(footer, BorderLayout.SOUTH);
		// Cards size to their content instead of a hardcoded height, so nothing is clipped.
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private JComponent hereLabel()
	{
		JLabel current = new JLabel("Here");
		current.setFont(FontManager.getRunescapeSmallFont());
		current.setForeground(GREEN);
		current.setToolTipText("You are on this world");
		return current;
	}

	static String minutes(long millis)
	{
		long minutes = Math.max(0, millis) / 60_000L;
		if (minutes < 1) return "under a minute";
		if (minutes < 60) return minutes + "m";
		return (minutes / 60) + "h " + (minutes % 60) + "m";
	}

	static String age(long millis)
	{
		long seconds = Math.max(0, millis) / 1000L;
		if (seconds < 60) return seconds + "s ago";
		return (seconds / 60) + "m ago";
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.knightfinder;

import com.google.inject.Provides;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "Knight Finder",
	description = "Find worlds where a Knight of Ardougne is trapped or held for pickpocketing",
	tags = {"knight", "ardougne", "thieving", "pickpocket", "split", "world"}
)
public class KnightFinderPlugin extends Plugin
{
	private static final int REFRESH_SECONDS = 15;
	/** Slower polling when only the notification wants the list, since nobody is looking at it. */
	private static final int BACKGROUND_REFRESH_SECONDS = 30;
	/** Ticks between reports while nothing about the knight changes. The server forgets a knight not heard from. */
	private static final int HEARTBEAT_TICKS = 50;
	/** Ticks between reports when only the number of people on the knight changed. */
	private static final int COUNT_CHANGE_TICKS = 10;
	/** A dragon spear shove or a moment out of view should not end a report. */
	private static final int LOST_GRACE_TICKS = 10;
	private static final Set<Integer> KNIGHT_IDS = new HashSet<>(Arrays.asList(
		NpcID.KNIGHT_OF_ARDOUGNE, NpcID.KNIGHT_OF_ARDOUGNE2, NpcID.KNIGHT_OF_ARDOUGNE_F,
		NpcID.KNIGHT_OF_ARDOUGNE_WEST, NpcID.KNIGHT_OF_ARDOUGNE_WEST_VIS,
		NpcID.KNIGHT_OF_ARDOUGNE_WEST_NOOP, NpcID.KNIGHT_OF_ARDOUGNE_WEST_NOOP_VIS,
		NpcID.KNIGHT_OF_ARDOUGNE_F_WEST, NpcID.KNIGHT_OF_ARDOUGNE_F_WEST_VIS));
	/** Worlds nobody can usefully be sent to for a knight. Knights are members' content, so F2P is out as well. */
	private static final EnumSet<WorldType> UNLISTED_WORLDS = EnumSet.of(WorldType.PVP, WorldType.HIGH_RISK,
		WorldType.DEADMAN, WorldType.SEASONAL, WorldType.TOURNAMENT_WORLD, WorldType.BETA_WORLD,
		WorldType.FRESH_START_WORLD, WorldType.NOSAVE_MODE, WorldType.PVP_ARENA,
		WorldType.QUEST_SPEEDRUNNING, WorldType.LAST_MAN_STANDING, WorldType.BOUNTY);

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private KnightFinderConfig config;
	@Inject private KnightFinderClient reportClient;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ScheduledExecutorService executor;
	@Inject private OverlayManager overlayManager;
	@Inject private KnightOverlay overlay;
	@Inject private Notifier notifier;

	private final Map<Integer, NPC> knights = new HashMap<>();
	private final KnightTracker tracker = new KnightTracker();
	private final AtomicBoolean refreshInFlight = new AtomicBoolean();
	private final Set<Integer> knownWorlds = ConcurrentHashMap.newKeySet();
	/** The pinned knight on this world right now, for the overlay. Null when there is none. */
	@Getter private volatile KnightTracker.Split currentSplit;
	private int tick;
	private int pinnedSinceTick;
	private boolean reported;
	private int lastReportTick;
	private int lastReportedCount;
	private int lostTicks;
	private volatile boolean primed;
	private volatile int currentWorld;
	private volatile boolean panelActive;
	private KnightFinderPanel panel;
	private NavigationButton navigationButton;
	private ScheduledFuture<?> refreshTask;

	@Override
	protected void startUp()
	{
		panel = new KnightFinderPanel(this::requestRefresh, this::setPanelActive);
		navigationButton = NavigationButton.builder()
			.tooltip("Knight Finder")
			.icon(ImageUtil.loadImageResource(KnightFinderPlugin.class, "knight.png"))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		overlayManager.add(overlay);
		// Enabling the plugin mid-session doesn't fire a game state change, so seed the world here.
		clientThread.invoke(() -> currentWorld = client.getGameState() == GameState.LOGGED_IN ? client.getWorld() : 0);
		restartRefreshTask();
	}

	@Override
	protected void shutDown()
	{
		stopRefreshTask();
		overlayManager.remove(overlay);
		panelActive = false;
		resetLocal();
		knownWorlds.clear();
		primed = false;
		refreshInFlight.set(false);
		currentWorld = 0;
		if (navigationButton != null) clientToolbar.removeNavigation(navigationButton);
		panel = null;
		navigationButton = null;
	}

	NPC knight(int npcIndex)
	{
		return knights.get(npcIndex);
	}

	/** How long the knight on this world has been pinned, in ticks. */
	int pinnedTicks()
	{
		return currentSplit == null ? 0 : tick - pinnedSinceTick;
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (KNIGHT_IDS.contains(npc.getId())) knights.put(npc.getIndex(), npc);
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		int index = event.getNpc().getIndex();
		if (knights.remove(index) != null) tracker.knightGone(index);
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		// This fires for every actor in the scene, so bail before touching anything else.
		Actor actor = event.getActor();
		if (knights.isEmpty() || actor.getAnimation() != AnimationID.HUMAN_PICKPOCKET || !(actor instanceof Player)) return;
		tracker.pickpocket(actor.getName(), actor.getWorldLocation(), tick);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tick++;
		for (Map.Entry<Integer, NPC> entry : knights.entrySet())
		{
			NPC npc = entry.getValue();
			tracker.knightSeen(entry.getKey(), npc.getWorldLocation(), npc.getInteracting() instanceof Player, tick);
		}
		KnightTracker.Split split = tracker.bestSplit(tick);
		if (split != null && (currentSplit == null || currentSplit.getNpcIndex() != split.getNpcIndex()))
		{
			// Pinned for at least the history the tracker needed to decide so; count from there.
			pinnedSinceTick = tick - KnightTracker.PINNED_TICKS;
		}
		currentSplit = split;
		share(split);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			currentWorld = client.getWorld();
			return;
		}
		if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			// Whatever was pinned here carries on without us; the server forgets it if nobody else is watching.
			currentWorld = 0;
			resetLocal();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!KnightFinderConfig.GROUP.equals(event.getGroup())) return;
		if (!config.sharingEnabled()) reported = false;
		restartRefreshTask();
	}

	private void resetLocal()
	{
		knights.clear();
		tracker.clear();
		currentSplit = null;
		reported = false;
		lostTicks = 0;
		lastReportedCount = 0;
	}

	private void share(KnightTracker.Split split)
	{
		if (!config.sharingEnabled() || currentWorld == 0 || !listableWorld()) return;
		if (split == null)
		{
			if (reported && ++lostTicks >= LOST_GRACE_TICKS)
			{
				reported = false;
				lostTicks = 0;
				reportClient.delete(currentWorld, () -> refresh(true), error -> { });
			}
			return;
		}
		lostTicks = 0;
		int since = tick - lastReportTick;
		boolean countChanged = split.getPickpockets() != lastReportedCount;
		if (reported && since < HEARTBEAT_TICKS && !(countChanged && since >= COUNT_CHANGE_TICKS)) return;
		reported = true;
		lastReportTick = tick;
		lastReportedCount = split.getPickpockets();
		KnightSplit report = new KnightSplit(currentWorld, split.getTile().getX(), split.getTile().getY(),
			split.getTile().getPlane(), KnightSpot.forPoint(split.getTile()),
			split.isHeld() ? KnightSplit.HELD : KnightSplit.TRAPPED, split.getPickpockets(), 0,
			Instant.now().toEpochMilli());
		reportClient.report(report, () -> refresh(true), error -> { });
	}

	private boolean listableWorld()
	{
		EnumSet<WorldType> types = client.getWorldType();
		return types.contains(WorldType.MEMBERS) && Collections.disjoint(types, UNLISTED_WORLDS);
	}

	private void setPanelActive(boolean active)
	{
		panelActive = active;
		if (active) restartRefreshTask();
		else stopRefreshTask();
	}

	private void requestRefresh()
	{
		executor.execute(() -> refresh(false));
	}

	private synchronized void restartRefreshTask()
	{
		stopRefreshTask();
		if (!config.sharingEnabled())
		{
			if (panel != null) SwingUtilities.invokeLater(panel::setDisabled);
			return;
		}
		// Poll while the sidebar is open, or while somebody wants to be told about new knights.
		if (!panelActive && !config.notifyNewSplit()) return;
		int interval = panelActive ? REFRESH_SECONDS : BACKGROUND_REFRESH_SECONDS;
		refreshTask = executor.scheduleWithFixedDelay(() -> refresh(false), 0, interval, TimeUnit.SECONDS);
	}

	private synchronized void stopRefreshTask()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}
	}

	/**
	 * @param fresh true after this client changed something. Such a refresh is never dropped for a
	 *              refresh already running, and asks any cache in front of the server to stand aside.
	 */
	private void refresh(boolean fresh)
	{
		if (!config.sharingEnabled() || panel == null) return;
		// Never stack requests - a slow or unreachable server would otherwise queue one every refresh.
		if (!refreshInFlight.compareAndSet(false, true) && !fresh) return;
		int world = currentWorld;
		SwingUtilities.invokeLater(panel::setLoading);
		reportClient.list(fresh,
			splits ->
			{
				refreshInFlight.set(false);
				announce(splits, world);
				SwingUtilities.invokeLater(() -> { if (panel != null) panel.setSplits(splits, world); });
			},
			error ->
			{
				refreshInFlight.set(false);
				SwingUtilities.invokeLater(() -> { if (panel != null) panel.setError(error); });
			});
	}

	private void announce(List<KnightSplit> splits, int world)
	{
		Set<Integer> seen = new HashSet<>();
		for (KnightSplit split : splits)
		{
			seen.add(split.getWorld());
			// The first list after enabling is not news, and neither is the knight we are stood next to.
			if (primed && config.notifyNewSplit() && split.getWorld() != world && !knownWorlds.contains(split.getWorld()))
			{
				notifier.notify("A knight is pinned on World " + split.getWorld() + " (" + split.getSpot() + ")");
			}
		}
		knownWorlds.clear();
		knownWorlds.addAll(seen);
		primed = true;
	}

	@Provides
	KnightFinderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(KnightFinderConfig.class);
	}
}

package com.knightfinder;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Outlines the pinned knight on this world, with how it is pinned and how many people are on it. */
class KnightOverlay extends Overlay
{
	private static final Color PINNED = new Color(90, 200, 120);
	private final KnightFinderPlugin plugin;
	private final KnightFinderConfig config;

	@Inject
	KnightOverlay(KnightFinderPlugin plugin, KnightFinderConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		KnightTracker.Split split = plugin.getCurrentSplit();
		if (split == null || !config.showOverlay()) return null;
		NPC knight = plugin.knight(split.getNpcIndex());
		if (knight == null) return null;
		Shape hull = knight.getConvexHull();
		if (hull != null) OverlayUtil.renderPolygon(graphics, hull, PINNED);
		String text = (split.isHeld() ? "Held" : "Trapped") + " · " + people(split.getPickpockets())
			+ " · " + duration(plugin.pinnedTicks());
		Point location = knight.getCanvasTextLocation(graphics, text, knight.getLogicalHeight() + 40);
		if (location != null) OverlayUtil.renderTextLocation(graphics, location, text, PINNED);
		return null;
	}

	static String people(int count)
	{
		return count == 1 ? "1 pickpocketing" : count + " pickpocketing";
	}

	static String duration(int ticks)
	{
		int seconds = (int) (ticks * 0.6);
		return seconds / 60 + ":" + String.format("%02d", seconds % 60);
	}
}

